    else:
        raise SQLSyntaxError(f"Unexpected token: {tokens[i].value}")

    if i < len(tokens) and tokens[i].type == TokenType.OPERATOR and tokens[i].value == ";":
        consume(TokenType.OPERATOR)

    consume(TokenType.EOF)

    return stmt


def parse_script(tokens: list[Token]) -> list[Statement]:
    """Parse zero or more ';'-separated statements up to EOF.

    Empty statements (consecutive ';' or a trailing ';') are skipped; an
    empty token stream (just EOF) yields ``[]``.

    Raises:
        SQLSyntaxError: if any statement is malformed.
    """
    statements = []
    i = 0
    while i < len(tokens) - 1:  # Stop before EOF
        start_i = i
        try:
            stmt = parse(tokens[i:])
            if isinstance(stmt, Statement):
                statements.append(stmt)
            i += len(tokens) - start_i - 1
            if i < len(tokens) and tokens[i].type == TokenType.OPERATOR and tokens[i].value == ";":
                i += 1
        except SQLSyntaxError:
            raise SQLSyntaxError(f"Malformed statement starting at token {start_i}")
    consume(TokenType.EOF)
    return statements


def parse_expression(tokens: list[Token]) -> Expr:
    """Parse a single WHERE-style expression that must consume every token
    up to EOF.

    Raises:
        SQLSyntaxError: if the tokens do not form exactly one expression.
    """
    def consume(expected_type: TokenType):
        if not tokens:
            raise SQLSyntaxError(f"Expected {expected_type.value}, got EOF")
        if tokens[0].type != expected_type:
            raise SQLSyntaxError(f"Expected {expected_type.value}, got {tokens[0].type.value}")
        return tokens.pop(0)

    def parse_primary() -> Expr:
        if tokens[0].type == TokenType.IDENTIFIER:
            return ColumnRef(consume(TokenType.IDENTIFIER).value)
        elif tokens[0].type == TokenType.INTEGER:
            return Literal(int(consume(TokenType.INTEGER).value))
        elif tokens[0].type == TokenType.STRING:
            return Literal(consume(TokenType.STRING).value)
        elif tokens[0].type == TokenType.KEYWORD and tokens[0].value == "TRUE":
            consume(TokenType.KEYWORD)
            return Literal(True)
        elif tokens[0].type == TokenType.KEYWORD and tokens[0].value == "FALSE":
            consume(TokenType.KEYWORD)
            return Literal(False)
        elif tokens[0].type == TokenType.KEYWORD and tokens[0].value == "NULL":
            consume(TokenType.KEYWORD)
            return Literal(None)
        elif tokens[0].type == TokenType.OPERATOR and tokens[0].value == "(":
            consume(TokenType.OPERATOR)
            expr = parse_expression(tokens)
            consume(TokenType.OPERATOR)
            return expr
        else:
            raise SQLSyntaxError(f"Unexpected token: {tokens[0].value}")

    def parse_predicate() -> Expr:
        left = parse_primary()
        if tokens and tokens[0].type == TokenType.KEYWORD and tokens[0].value == "IS":
            consume(TokenType.KEYWORD)
            negated = False
            if tokens and tokens[0].type == TokenType.KEYWORD and tokens[0].value == "NOT":
                consume(TokenType.KEYWORD)
                negated = True
            consume(TokenType.KEYWORD)
            if tokens and tokens[0].type != TokenType.KEYWORD or tokens[0].value != "NULL":
                raise SQLSyntaxError("Expected NULL after IS [NOT] NULL")
            consume(TokenType.KEYWORD)
            return IsNull(left, negated)
        elif tokens and tokens[0].type == TokenType.OPERATOR and tokens[0].value in COMPARISON_OPS:
            op = consume(TokenType.OPERATOR).value
            right = parse_primary()
            return Comparison(op, left, right)
        else:
            return left

    def parse_not_expr() -> Expr:
        if tokens and tokens[0].type == TokenType.KEYWORD and tokens[0].value == "NOT":
            consume(TokenType.KEYWORD)
            return Not(parse_not_expr())
        else:
            return parse_predicate()

    def parse_and_expr() -> Expr:
        expr = parse_not_expr()
        while tokens and tokens[0].type == TokenType.KEYWORD and tokens[0].value == "AND":
            consume(TokenType.KEYWORD)
            expr = And(expr, parse_not_expr())
        return expr

    def parse_or_expr() -> Expr:
        expr = parse_and_expr()
        while tokens and tokens[0].type == TokenType.KEYWORD and tokens[0].value == "OR":
            consume(TokenType.KEYWORD)
            expr = Or(expr, parse_and_expr())
        return expr

    if not tokens:
        raise SQLSyntaxError("No tokens to parse")

    expr = parse_or_expr()

    if tokens:
        raise SQLSyntaxError("Trailing tokens after expression")

    return expr
